:root {
  --color-primary: #0052cc;
  --color-primary-dark: #003a99;
  --color-accent: #00d4ff;
  --color-accent-on-dark: #00d4ff;
  --color-bg-light: #f9f9fb;
  --color-bg-dark: #1a1a2e;
  --color-text-dark: #1f2937;
  --color-text-light: #f5f7fa;
  --color-border: #e5e7eb;
  --color-success: #059669;
  --color-success-bg: #ecfdf5;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --font-mono: "Courier New", monospace;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --max-width: 1200px;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text-dark);
  background-color: #fff;
  line-height: 1.6;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  width: 100%;
}

/* Header */
.site-header {
  background-color: #fff;
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  font-family: var(--font-mono);
  font-size: clamp(1.25rem, 5vw, 1.5rem);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-primary);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-xs);
  transition: var(--transition);
}

.logo:hover,
.logo:focus {
  color: var(--color-primary-dark);
  outline: none;
}

.logo:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Footer */
.site-footer {
  background-color: var(--color-bg-dark);
  color: var(--color-text-light);
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
  text-align: center;
  font-size: 0.9rem;
}

.site-footer a {
  color: var(--color-accent);
  text-decoration: none;
  transition: var(--transition);
}

.site-footer a:hover,
.site-footer a:focus {
  text-decoration: underline;
}

.site-footer a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
}

/* Typography */
h1, h2, h3 {
  font-weight: 700;
  line-height: 1.3;
}

h1 {
  font-size: clamp(1.875rem, 6vw, 2.5rem);
}

h2 {
  font-size: clamp(1.5rem, 5vw, 2rem);
}

h3 {
  font-size: clamp(1.125rem, 4vw, 1.5rem);
}

p {
  margin-bottom: var(--spacing-md);
}

strong {
  font-weight: 700;
}

/* Links */
a {
  color: var(--color-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--color-primary-dark);
}

a:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Buttons */
button, .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-sm) var(--spacing-md);
  min-height: 44px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #fff;
}

.btn-primary:hover,
.btn-primary:active {
  background-color: var(--color-primary-dark);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--color-primary-dark);
  outline-offset: 2px;
}

.btn-secondary {
  background-color: var(--color-bg-light);
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-secondary:hover,
.btn-secondary:active {
  background-color: #f0f0f6;
}

.btn-secondary:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Forms */
label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text-dark);
}

input, textarea, select {
  display: block;
  width: 100%;
  padding: var(--spacing-sm);
  min-height: 44px;
  font-family: inherit;
  font-size: 1rem;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  transition: var(--transition);
}

input:focus, textarea:focus, select:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 0;
  border-color: var(--color-primary);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

/* Cards */
.card {
  background-color: #fff;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 10px 30px rgba(0, 82, 204, 0.1);
  border-color: var(--color-accent);
}

.card.featured {
  border-color: var(--color-primary);
  box-shadow: 0 10px 30px rgba(0, 82, 204, 0.15);
  position: relative;
}

.card.featured::before {
  content: "Most Popular";
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-primary);
  color: #fff;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: 1fr;
}

.grid-3 {
  grid-template-columns: 1fr;
}

/* Responsive */
@media (max-width: 600px) {
  :root {
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.25rem;
  }

  .card {
    padding: var(--spacing-md);
  }

  table {
    font-size: 0.875rem;
  }
}

@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 769px) {
  .container {
    padding: 0 var(--spacing-lg);
  }
}

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
  margin: var(--spacing-lg) 0;
}

thead {
  background-color: var(--color-bg-light);
}

th {
  padding: var(--spacing-md);
  text-align: left;
  font-weight: 700;
  border-bottom: 2px solid var(--color-border);
}

td {
  padding: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
}

tbody tr:nth-child(odd) {
  background-color: #fafbfc;
}

.check {
  color: var(--color-success);
  font-weight: 700;
}

.cross {
  color: #d1d5db;
  font-weight: 700;
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Print */
@media print {
  .site-header,
  .site-footer {
    display: none;
  }
}

pages.css:
.pricing-hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: #fff;
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.pricing-hero h1 {
  color: #fff;
  margin-bottom: var(--spacing-md);
}

.pricing-tagline {
  font-size: 1.125rem;
  opacity: 0.95;
  margin-bottom: 0;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.pricing-plans {
  padding: var(--spacing-2xl) 0;
  background-color: #fff;
}

.pricing-card {
  display: flex;
  flex-direction: column;
}

.pricing-card h2 {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-dark);
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-xs);
  margin-bottom: var(--spacing-lg);
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
}

.pricing-period {
  font-size: 0.9rem;
  color: #6b7280;
}

.pricing-description {
  font-size: 0.95rem;
  color: #6b7280;
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.pricing-btn {
  width: 100%;
  margin-bottom: var(--spacing-lg);
}

.pricing-features {
  list-style: none;
  flex-grow: 1;
}

.pricing-features li {
  padding: var(--spacing-sm) 0;
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  color: var(--color-text-dark);
}

.pricing-features .check {
  min-width: 20px;
  text-align: center;
}

.pricing-features .cross {
  min-width: 20px;
  text-align: center;
}

.pricing-comparison {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-light);
}

.pricing-comparison h2 {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.pricing-table-wrapper {
  overflow-x: auto;
}

.pricing-table {
  background-color: #fff;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.pricing-table thead {
  background-color: var(--color-primary);
  color: #fff;
}

.pricing-table th {
  color: #fff;
  border-bottom-color: var(--color-primary-dark);
  font-weight: 700;
}

.pricing-table tbody tr:nth-child(odd) {
  background-color: #fafbfc;
}

.pricing-faq {
  padding: var(--spacing-2xl) 0;
  background-color: #fff;
}

.pricing-faq h2 {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: 6px;
  margin-bottom: var(--spacing-md);
  overflow: hidden;
}

.faq-item summary {
  display: flex;
  align-items: center;
  padding: var(--spacing-md);
  cursor: pointer;
  font-weight: 600;
  color: var(--color-text-dark);
  background-color: #fafbfc;
  user-select: none;
  transition: var(--transition);
  min-height: 44px;
}

.faq-item summary:hover {
  background-color: #f3f4f6;
}

.faq-item summary::marker {
  color: var(--color-primary);
}

.faq-item[open] summary {
  background-color: #f0f4ff;
  border-bottom: 1px solid var(--color-border);
}

.faq-item[open] summary::marker {
  color: var(--color-primary-dark);
}

.faq-item p {
  padding: var(--spacing-md);
  color: #6b7280;
  background-color: #fff;
  margin-bottom: 0;
}

.faq-item a {
  color: var(--color-primary);
  font-weight: 600;
  text-decoration: underline;
}

/* Mobile */
@media (max-width: 600px) {
  .pricing-hero {
    padding: var(--spacing-xl) 0;
  }

  .pricing-hero h1 {
    font-size: 1.75rem;
  }

  .pricing-tagline {
    font-size: 1rem;
  }

  .pricing-plans {
    padding: var(--spacing-xl) 0;
  }

  .pricing-amount {
    font-size: 2rem;
  }

  .pricing-card.featured::before {
    font-size: 0.7rem;
    padding: 3px 10px;
  }

  .pricing-comparison {
    padding: var(--spacing-xl) 0;
  }

  .pricing-table-wrapper {
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  }

  .pricing-table {
    font-size: 0.85rem;
  }

  .pricing-table th,
  .pricing-table td {
    padding: var(--spacing-sm);
  }

  .pricing-faq {
    padding: var(--spacing-xl) 0;
  }

  .faq-item summary {
    padding: var(--spacing-md);
    font-size: 0.95rem;
  }

  .faq-item p {
    padding: var(--spacing-md);
    font-size: 0.9rem;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .pricing-hero {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .faq-item summary:hover {
    color: var(--color-primary);
  }
}

/* Tablet adjustments */
@media (min-width: 601px) and (max-width: 768px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-card:nth-child(3) {
    grid-column: 1 / -1;
    max-width: 50%;
    margin: 0 auto;
  }
}

