  margin-right: auto;
}

.pricing-plans {
  padding: var(--spacing-2xl) 0;
  background-color: #fff;
}

.pricing-card {
  display: flex;
  flex-direction: column;
}

.pricing-card h2 {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-dark);
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-xs);
  margin-bottom: var(--spacing-lg);
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary);
}

.pricing-period {
  font-size: 0.9rem;
  color: #6b7280;
}

.pricing-description {
  font-size: 0.95rem;
  color: #6b7280;
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.pricing-btn {
  width: 100%;
  margin-bottom: var(--spacing-lg);
}

.pricing-features {
  list-style: none;
  flex-grow: 1;
}

.pricing-features li {
  padding: var(--spacing-sm) 0;
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  color: var(--color-text-dark);
}

.pricing-features .check {
  min-width: 20px;
  text-align: center;
}

.pricing-features .cross {
  min-width: 20px;
  text-align: center;
}

.pricing-comparison {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-light);
}

.pricing-comparison h2 {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.pricing-table-wrapper {
  overflow-x: auto;
}

.pricing-table {
  background-color: #fff;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.pricing-table thead {
  background-color: var(--color-primary);
  color: #fff;
}

.pricing-table th {
  color: #fff;
  border-bottom-color: var(--color-primary-dark);
  font-weight: 700;
}

.pricing-table tbody tr:nth-child(odd) {
  background-color: #fafbfc;
}

.pricing-faq {
  padding: var(--spacing-2xl) 0;
  background-color: #fff;
}

.pricing-faq h2 {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: 6px;
  margin-bottom: var(--spacing-md);
  overflow: hidden;
}

.faq-item summary {
  display: flex;
  align-items: center;
  padding: var(--spacing-md);
  cursor: pointer;
  font-weight: 600;
  color: var(--color-text-dark);
  background-color: #fafbfc;
  user-select: none;
  transition: var(--transition);
  min-height: 44px;
}

.faq-item summary:hover {
  background-color: #f3f4f6;
}

.faq-item summary::marker {
  color: var(--color-primary);
}

.faq-item[open] summary {
  background-color: #f0f4ff;
  border-bottom: 1px solid var(--color-border);
}

.faq-item[open] summary::marker {
  color: var(--color-primary-dark);
}

.faq-item p {
  padding: var(--spacing-md);
  color: #6b7280;
  background-color: #fff;
  margin-bottom: 0;
}

.faq-item a {
  color: var(--color-primary);
  font-weight: 600;
  text-decoration: underline;
}

/* Mobile */
@media (max-width: 600px) {
  .pricing-hero {
    padding: var(--spacing-xl) 0;
  }

  .pricing-hero h1 {
    font-size: 1.75rem;
  }

  .pricing-tagline {
    font-size: 1rem;
  }

  .pricing-plans {
    padding: var(--spacing-xl) 0;
  }

  .pricing-amount {
    font-size: 2rem;
  }

  .pricing-card.featured::before {
    font-size: 0.7rem;
    padding: 3px 10px;
  }

  .pricing-comparison {
    padding: var(--spacing-xl) 0;
  }

  .pricing-table-wrapper {
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  }

  .pricing-table {
    font-size: 0.85rem;
  }

  .pricing-table th,
  .pricing-table td {
    padding: var(--spacing-sm);
  }

  .pricing-faq {
    padding: var(--spacing-xl) 0;
  }

  .faq-item summary {
    padding: var(--spacing-md);
    font-size: 0.95rem;
  }

  .faq-item p {
    padding: var(--spacing-md);
    font-size: 0.9rem;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .pricing-hero {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .faq-item summary:hover {
    color: var(--color-primary);
  }
}

/* Tablet adjustments */
@media (min-width: 601px) and (max-width: 768px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-card:nth-child(3) {
    grid-column: 1 / -1;
    max-width: 50%;
    margin: 0 auto;
  }
}
